"""File persistence, trees, verification and network filesystem lessons."""
def register(topic,q,detail):
    topic('Readahead·순차 접근 예측','파일시스템','mm/readahead.c','page_cache_sync_ra',
      '요청한 데이터만 매번 저장장치에서 기다리면 순차 읽기가 늦어질 수 있어 다음 범위를 미리 준비합니다.',
      'Readahead는 파일의 읽기 위치와 이전 창을 보고 다음 folio 범위의 I/O를 미리 제출합니다. 현재 필요한 영역과 비동기 선행 영역을 구분하고 표시된 folio를 읽으면 다음 창을 진행시킵니다. 예측이 빗나가면 메모리·I/O 낭비가 생깁니다.',
      '순차·랜덤 접근을 구분하고 posix_fadvise 같은 힌트와 실제 처리량을 비교합니다. 미리 읽기 실패와 실제 필요한 read 실패를 구분하며 캐시가 이미 채워진 경우도 고려합니다.',
      'page_cache_sync_ra와 page_cache_async_ra의 index·size·async_size·readahead 표식을 연결하세요.',
      q('선행 읽기 예측이 빗나가 사용하지 않은 페이지가 많으면 어떤 비용이 생기는가?','추가 I/O와 캐시 메모리 사용','디스크 공간이 자동으로 절약됨','예측 데이터도 읽기와 메모리를 소비합니다. 순차 접근에 이로운 전략이 랜덤 접근에서는 비용이 될 수 있습니다.'),
      q('Readahead가 모든 folio를 읽지 못하면 곧바로 최종 사용자 읽기 오류인가?','실제 필요한 folio의 읽기 경로에서 다시 처리할 수 있다','선행 읽기 미완료는 모두 최종 오류다','원본 주석은 readahead 미완료 folio를 read_folio 경로가 처리하고 그 실패를 최종 오류로 삼는다고 설명합니다.'),
      details=[detail('창 상태','file_ra_state는 이전 읽기 위치와 선행 범위 상태를 담습니다. 창의 start·size와 비동기 tail의 async_size를 구분하세요. 블록 장치의 단순 sector 번호와 파일의 page index도 단위가 다릅니다.'),detail('현재 버전의 진입점','v6.12의 page_cache_sync_ra·async_ra를 기준으로 읽습니다. 다른 버전의 ondemand_readahead라는 함수 이름을 그대로 따라가면 현재 파일에 없는 진입점을 찾게 됩니다.')])

    topic('Fsync·데이터와 메타데이터의 영구 반영','파일시스템','fs/sync.c','do_fsync',
      'write가 성공해도 캐시에만 남은 데이터는 장애 때 없어질 수 있어 영구 저장 경계를 알아야 합니다.',
      'fsync는 파일 데이터와 관련 메타데이터의 저장을 요청하고 오류를 반환합니다. fdatasync는 데이터 접근에 필요한 메타데이터 중심으로 동기화합니다. 파일 생성·rename의 디렉터리 항목과 파일 데이터는 별도 대상이므로 파일 하나의 fsync만으로 전체 작업의 crash consistency가 완성되지는 않습니다.',
      'write 반환값→fsync 반환값을 모두 확인합니다. 내구성 있는 파일 교체는 임시 파일 쓰기·파일 동기화·rename·관련 디렉터리 동기화 같은 규약과 파일시스템·장치 조건을 검토합니다.',
      'do_fsync에서 fdget→vfs_fsync→fdput과 fsync·fdatasync의 datasync 값을 비교하세요.',
      q('write 성공이 전원 차단 뒤의 데이터 보존까지 항상 보장하는가?','아니다. 영구 반영과 반환 오류를 따로 확인한다','캐시에 썼다면 항상 보존된다','write의 완료와 저장장치의 내구성 경계는 다를 수 있습니다. fsync도 오류를 반환할 수 있어 결과를 확인해야 합니다.'),
      q('새 파일 내용만 fsync하면 그 이름의 디렉터리 항목까지 항상 보장되는가?','관련 디렉터리 동기화 규약도 검토한다','파일 fsync 하나면 모든 디렉터리 변경이 보장된다','파일 내용과 디렉터리의 이름 연결은 서로 다른 변경입니다. 내구성 요구에 맞게 관련 대상을 동기화합니다.'),
      details=[detail('호출 계층','do_fsync는 fd 유효성과 참조 수명을 관리하고 vfs_fsync는 파일시스템별 구현으로 이어집니다. 파일시스템은 dirty page·저널·장치 flush 등 자기 규약을 따릅니다.'),detail('Crash consistency와 원자성','fsync 하나가 여러 파일의 변경을 트랜잭션으로 묶지는 않습니다. 어느 시점에서 장애가 나도 허용되는 상태를 먼저 정하고 파일·디렉터리·rename 순서를 설계합니다.')])

    topic('F2FS·로그 구조와 Garbage Collection','파일시스템','fs/f2fs/gc.c','f2fs_gc',
      '플래시 저장장치에서 갱신을 새 위치에 기록하면 오래된 영역의 유효 데이터와 빈 공간을 정리해야 합니다.',
      'F2FS는 segment 단위의 로그 구조를 활용합니다. 갱신은 새 위치에 쓰고 이전 블록은 무효화됩니다. GC는 victim의 유효 블록을 다른 공간으로 옮긴 뒤 segment를 회수합니다. 유효 블록 비율·비용·age·여유 공간 등이 정책에 영향을 줍니다.',
      '빈 공간과 GC 비용을 관찰하며 읽기·쓰기 패턴을 비교합니다. GC의 이동 I/O와 사용자 쓰기의 write amplification을 구분합니다. background와 foreground GC의 실행 문맥·완료 조건을 읽습니다.',
      'f2fs_gc의 gc_control·victim 선택·유효 블록 이동·free segment 계산을 연결하세요.',
      q('100블록 segment에 유효 블록 20개가 남아 있으면 회수 전 무엇이 필요한가?','유효 20블록을 보존하도록 옮긴다','유효 데이터도 모두 버린다','아직 참조되는 데이터는 다른 위치에 기록하고 매핑을 갱신해야 합니다. 이후 옛 segment를 재사용할 수 있습니다.'),
      q('GC가 추가 쓰기를 발생시키는 이유는?','살아 있는 데이터를 옮겨 빈 segment를 만들기 때문','원본 파일이 항상 두 배로 커지기 때문','논리 파일 크기는 같아도 저장장치에 유효 블록 이동 쓰기가 생깁니다. 이를 사용자 쓰기와 구분해 비용을 계산합니다.'),
      details=[detail('주소 매핑','데이터와 노드 위치가 바뀌어도 파일 의미를 유지하도록 NAT·SIT 등 메타데이터와 checkpoint를 관리합니다. segment 회수와 변경의 내구성은 따로 연결해 읽어야 합니다.'),detail('GC 목록과 오류','gc_inode_list는 이동할 inode를 모으며 free section 수는 진행 조건에 사용됩니다. 동시 수정·이동 실패·checkpoint 조건을 확인해야 회수했다는 판단이 정확합니다.')])

    topic('XFS·할당 그룹과 B-tree','파일시스템','fs/xfs/libxfs/xfs_alloc.c','xfs_alloc_vextent_this_ag',
      '큰 파일시스템의 빈 공간을 한곳에서만 관리하면 검색과 동시 할당의 경쟁이 커질 수 있습니다.',
      'XFS는 주소 공간을 allocation group으로 나눠 지역 메타데이터와 할당을 관리합니다. AG의 free-space B-tree는 시작 블록 기준과 길이 기준 검색을 지원합니다. 요청의 최소·최대 길이·정렬·목표 위치를 맞추며 공간이 있더라도 제약에 맞는 extent가 없을 수 있습니다.',
      'xfs_alloc_arg의 단위와 요청 제약을 확인하고 AG 선택→freelist 준비→extent 할당→트랜잭션 변경을 연결합니다. 전체 남은 바이트가 요청보다 많다는 이유만으로 연속 할당 성공을 가정하지 않습니다.',
      'xfs_alloc_vextent_this_ag와 xfs_alloc_vextent_check_args, allocbt의 두 검색 순서를 읽으세요.',
      q('4블록씩 떨어진 빈 공간이 10개 있으면 반드시 20블록 연속 extent를 얻는가?','전체 빈 공간과 연속 extent는 다르다','총 40블록이므로 반드시 성공한다','연속 요청은 한 범위의 길이·정렬 조건을 만족해야 합니다. 여러 작은 빈 공간의 합만으로 보장되지 않습니다.'),
      q('Allocation group으로 나누는 목적 중 하나는?','지역 할당 관리와 병렬성 확보','모든 파일을 같은 블록으로 저장','AG별 메타데이터를 관리해 여러 할당의 경쟁을 나눌 수 있습니다. 그룹 사이 선택 정책과 트랜잭션 제약도 필요합니다.'),
      details=[detail('두 B-tree의 검색','같은 빈 extent를 주소 기준으로 정렬하면 위치 근처를, 길이 기준으로 정렬하면 크기에 맞는 공간을 찾기 쉽습니다. 서로 다른 검색 질문에 맞춘 중복 인덱스입니다. 변경 시 둘의 일관성을 유지해야 합니다.'),detail('잠금 순서','AG를 여러 개 탐색할 때 잠금 순서와 트랜잭션 조건이 교착 방지에 관련됩니다. minimum_agno와 TRYLOCK 경로를 단순 성능 옵션으로만 해석하지 않습니다.')])

    topic('Bcachefs·버전과 B-tree','파일시스템','fs/bcachefs/btree_iter.c','bch2_btree_iter_peek_upto',
      '변하는 저장 메타데이터를 B-tree에서 읽을 때 키의 위치·버전·snapshot·동시 변경을 함께 고려해야 합니다.',
      'Bcachefs의 B-tree iterator는 inode·offset·snapshot 등이 들어가는 키 위치와 transaction 경로를 가지고 탐색합니다. peek_upto는 현재 위치 이상에서 한계 이하의 키를 찾습니다. 트랜잭션 재시작 오류와 실제 키 없음은 구분하며 snapshot의 가시성 규약도 따릅니다.',
      'bpos·bkey_s_c·btree_iter·btree_trans의 역할을 구분합니다. 반환된 키의 수명과 bkey_err를 확인하며 transaction이 재시작되면 필요한 탐색을 규약대로 다시 수행합니다.',
      'bch2_btree_iter_peek_upto의 search_key·end와 __bch2_btree_iter_peek를 읽으세요.',
      q('정렬된 위치 3·7·10에서 현재 위치 5, end 8인 peek가 찾을 후보는?','7','10','현재 이상인 첫 위치는 7이며 한계 8 이하입니다. 이는 정렬된 키 탐색을 단순화한 예이고 snapshot 조건은 따로 적용됩니다.'),
      q('트랜잭션 재시작 오류와 키 없음은 같은 뜻인가?','별도 상태로 처리해야 한다','둘 다 무조건 정상 키다','bkey_err로 오류를 구분해야 합니다. 재시작은 잠금·경로 등을 다시 마련해야 하는 상태이며 끝에 도달한 것과 다릅니다.'),
      details=[detail('위치의 자료구조','파일 번호와 파일 내부 offset, snapshot 식별자를 묶은 위치는 정수 offset 하나보다 정보가 많습니다. 비교·검색 순서와 snapshot 가시성을 읽어야 어느 키가 반환되는지 이해합니다.'),detail('반환값 수명','iterator가 참조하는 노드와 transaction lock의 수명 안에서 키를 사용해야 합니다. 단순히 포인터를 다른 곳에 저장했다고 노드 내용이 영구 유효해지는 것은 아닙니다.')])

    topic('Fscrypt·파일 이름과 내용의 암호화','파일시스템','fs/crypto/keysetup.c','fscrypt_get_encryption_info',
      '파일시스템 암호화는 파일 내용뿐 아니라 이름·정책·키의 수명과 접근 조건을 관리해야 합니다.',
      'Fscrypt는 inode의 암호화 context에서 정책을 읽고 master key로 필요한 암호 정보를 준비합니다. 파일시스템이 지원하는 내용·이름 암호화 모드와 IV 규약을 따릅니다. 디스크의 암호화 정책이 존재하는 것과 현재 사용 가능한 키가 있는 것은 다릅니다.',
      '지원 파일시스템에서 정책을 설정하고 key 추가·제거와 허용되는 파일 작업을 확인합니다. 암호화된 저장 내용의 비밀성과 메타데이터 노출 범위·무결성 요구를 구분합니다.',
      'fscrypt_get_encryption_info의 context→policy→key 준비와 allow_unsupported 처리를 읽으세요.',
      q('inode에 암호화 정책이 있으면 현재 키도 반드시 있는가?','정책과 사용 가능한 키 상태는 다르다','정책 자체가 모든 비밀 키다','정책은 모드와 key 식별 등 규약을 담고 키의 가용성은 별도입니다. 키가 없을 때 허용되는 동작도 구분해야 합니다.'),
      q('Fscrypt 사용만으로 모든 저장 데이터의 변조 검출이 항상 제공되는가?','암호화와 무결성 보장을 구분해야 한다','어떤 모드든 인증 tag가 자동 제공된다','저장 암호의 모드와 검증 기능은 다릅니다. fs-verity 등 별도 검증 기술도 목적과 적용 범위를 확인해야 합니다.'),
      details=[detail('Context의 검증','get_context 결과 길이·내용에서 정책을 해석합니다. 지원하지 않는 정책과 손상된 context를 처리하는 오류 경로를 보세요. 반환 0만 보고 언제나 key가 준비됐다고 판단해서는 안 됩니다.'),detail('파일별 키와 IV','공통 master key를 각 파일에 그대로 반복 적용하는 단순 모델보다 파일별 파생·nonce·IV 구성이 더 중요합니다. 정책 버전과 암호 모드의 실제 규약을 확인해야 위치별 변환을 설명할 수 있습니다.')])

    topic('Fs-verity·Merkle Tree로 파일 검증','파일시스템','fs/verity/verify.c','fsverity_verify_blocks',
      '큰 파일의 일부를 읽을 때도 전체를 다시 해시하지 않고 신뢰할 요약과 일치하는지 확인해야 합니다.',
      'Fs-verity는 데이터 블록의 해시를 다시 해시하는 Merkle tree를 사용합니다. 읽은 블록에서 상위 해시를 따라 검증해 신뢰한 파일 digest와 연결합니다. Enable 뒤 내용은 읽기 전용이며 digest의 신뢰를 앱이 확보해야 악의적인 파일 교체도 구분할 수 있습니다.',
      '지원 파일시스템의 enable·measure와 앱의 신뢰한 digest 또는 서명 검증을 연결합니다. 데이터 검증 실패는 오류로 처리합니다. 해시 트리가 암호화나 파일 이름의 신뢰까지 자동 제공한다고 가정하지 않습니다.',
      'fsverity_verify_blocks→verify_data_blocks와 hash block의 상위 검증을 읽으세요.',
      q('파일과 해시 트리를 공격자가 함께 바꾸는데 신뢰한 digest를 확인하지 않으면 충분한가?','외부에서 신뢰한 digest와 연결해야 한다','트리가 존재하면 어떤 교체도 항상 검출된다','공격자가 새 파일의 올바른 트리까지 만들 수 있습니다. 신뢰한 기준 digest 또는 그 서명과 비교해야 진위를 판별합니다.'),
      q('Merkle tree는 일부 블록 검증에 왜 유리한가?','해당 블록에서 루트까지의 경로를 검증할 수 있어서','검증할 블록 내용을 읽지 않아도 되어서','해당 데이터 해시와 상위 경로를 검증하므로 전체 파일을 매번 다시 해시할 필요가 없습니다. 읽은 블록 자체의 검증은 필요합니다.'),
      details=[detail('트리 계산 예','데이터 A·B의 H(A), H(B)를 묶어 상위 H(H(A)||H(B))를 만든다고 가정하세요. A를 바꾸면 A의 해시와 상위 값이 달라집니다. 실제 구현은 블록 크기·salt·descriptor·파일 digest 규약을 함께 따릅니다.'),detail('Folio와 유효 범위','v6.12의 fsverity_verify_blocks는 folio·len·offset을 받아 범위를 검증합니다. Folio lock과 uptodate 전제는 검증 중 데이터 변경과 읽기 완료의 순서를 맞추기 위한 조건입니다.')])

    topic('DAX·페이지 캐시를 거치지 않는 매핑','파일시스템','fs/dax.c','dax_iomap_rw',
      'CPU가 직접 접근 가능한 저장 메모리에서는 일반 페이지 캐시 복사 경로를 줄일 수 있습니다.',
      'Filesystem DAX는 지원 저장 메모리를 파일 offset에 대응시켜 일반 페이지 캐시를 거치지 않는 접근을 제공합니다. iomap은 파일 범위와 저장 주소를 연결합니다. 직접 매핑이 가능해도 저장장치의 내구성·캐시 flush·동기화와 잠금 규약은 여전히 필요합니다.',
      '파일시스템·장치의 DAX 지원과 실제 파일 속성을 확인합니다. mmap·read/write에서 매핑 수명·truncate·동시 접근을 고려하며 직접 접근과 영구 반영을 같은 개념으로 취급하지 않습니다.',
      'dax_iomap_rw의 IOMAP_DAX·IOMAP_WRITE·NOWAIT와 inode 잠금 조건을 읽으세요.',
      q('DAX가 페이지 캐시를 거치지 않으면 fsync 등 내구성 검토도 없어지는가?','저장 지속성과 동기화 규약은 별도다','모든 CPU 쓰기가 즉시 영구 저장된다','CPU 캐시와 저장 메모리의 지속성 경계가 남습니다. 파일시스템과 플랫폼의 flush·동기화 규약을 따라야 합니다.'),
      q('iomap이 연결하는 두 범위는?','파일 논리 offset과 저장 매핑','항상 두 프로세스 PID','파일 데이터 위치를 저장 범위에 대응시키는 추상화입니다. DAX는 그 매핑에 직접 접근 가능한 장치라는 조건을 더합니다.'),
      details=[detail('접근 방식의 변화','일반 읽기는 저장 데이터→페이지 캐시→사용자 버퍼의 단계를 거칠 수 있습니다. DAX는 저장 메모리의 직접 접근을 활용합니다. 모든 종류의 SSD가 CPU 직접 load/store에 적합한 DAX 메모리인 것은 아닙니다.'),detail('Hole·쓰기·오류','Hole과 extent, 매핑 범위 끝, 쓰기 잠금, NOWAIT 조건을 처리해야 합니다. 캐시를 생략해도 VFS의 파일 크기·오류·동시성 계약은 없어지지 않습니다.')])

    topic('SquashFS·읽기 전용 압축 파일시스템','파일시스템','fs/squashfs/super.c','squashfs_fill_super',
      '배포 이미지의 파일을 작게 묶고 실행 중 변경하지 않는 저장 형식이 필요할 수 있습니다.',
      'SquashFS는 파일 데이터와 메타데이터를 압축된 이미지에 저장하고 읽을 때 필요한 블록을 복원합니다. Superblock의 압축 방식·테이블 위치·inode·fragment 정보를 해석합니다. 읽기 전용 이미지 수정과 일반 파일시스템 쓰기는 다른 작업입니다.',
      'mksquashfs로 이미지를 만들고 지원 커널에서 읽기 전용으로 마운트합니다. 쓰기 공간이 필요한 경우 별도 상위 계층 등 설계를 사용합니다. 압축 블록 단위의 랜덤 읽기 비용도 측정합니다.',
      'squashfs_fill_super의 magic·압축기·table 위치 검증과 root inode 생성까지 읽으세요.',
      q('마운트된 SquashFS 안의 파일을 일반 write로 직접 변경할 수 있는가?','읽기 전용 형식이므로 직접 변경하지 않는다','항상 제자리 갱신된다','이미지 제작과 마운트 뒤 읽기는 다른 단계입니다. 변경이 필요한 경우 새 이미지나 별도의 쓰기 계층이 필요합니다.'),
      q('압축 블록의 작은 일부만 읽어도 어떤 비용이 있을 수 있는가?','해당 압축 블록의 복원 작업','모든 경우 CPU 비용이 0','압축 단위와 요청 길이가 다를 수 있습니다. 저장 크기 절약과 복원 CPU·메모리 비용을 함께 봅니다.'),
      details=[detail('Fragment의 용도','파일 끝의 작은 조각을 fragment block에 모아 낭비를 줄일 수 있습니다. 일반 완전 블록과 파일 끝 위치를 찾는 메타데이터가 다르므로 데이터 offset 하나만으로 읽을 수 없습니다.'),detail('이미지 입력 검증','크기·테이블 offset·지원 압축기를 검사하고 실패 시 마련한 상태를 해제합니다. 읽기 전용이라는 사실이 손상되거나 악의적인 이미지에 대한 검증 필요를 없애지 않습니다.')])

    topic('UBIFS·플래시 인덱스와 저널','파일시스템','fs/ubifs/super.c','ubifs_mount',
      'Raw flash는 덮어쓰기·erase block·bad block 특성이 있어 일반 블록 저장장치와 다른 계층이 필요합니다.',
      'UBIFS는 UBI volume 위에서 작동하며 UBI의 erase block 관리와 별도로 파일시스템 인덱스·저널·commit을 관리합니다. 변경 노드를 기록하고 tree node cache로 인덱스를 관리합니다. NAND의 erase 제약과 GC·장애 복구까지 연결해야 갱신 과정을 이해할 수 있습니다.',
      'MTD→UBI→UBIFS 계층을 구분하고 지원된 테스트 장치나 VM에서 image·volume·mount 규약을 확인합니다. 실제 플래시의 erase·format은 데이터를 바꾸므로 학습용 장치에서만 수행합니다.',
      'ubifs_mount의 open_ubi와 mount, replay·commit 경로를 연결하세요.',
      q('UBIFS가 일반적으로 올라가는 계층은?','UBI volume','어떤 파일의 사용자 포인터 하나','UBI가 raw flash 관리와 volume을 제공하고 UBIFS가 그 위의 파일·인덱스·저널을 제공합니다.'),
      q('Flash의 erase block 특성 때문에 필요한 관리 중 하나는?','새 위치 기록과 erase·GC 관리','임의 바이트를 제한 없이 덮어쓰기','쓰기와 erase 단위·횟수 제약을 고려해야 합니다. 파일 내용 변경이 단순 제자리 바이트 교체로 끝나지 않습니다.'),
      details=[detail('TNC와 인덱스','Tree node cache는 디스크 인덱스의 메모리 상태를 관리합니다. 새 노드 기록과 commit 뒤 참조를 이어가야 장애 후에도 어느 버전이 유효한지 결정할 수 있습니다.'),detail('Mount의 자원 수명','처음 UBI를 읽기 전용으로 열어 정보를 확인하고 이미 존재하는 mount와 충돌을 피합니다. 오류 포인터·volume 참조·superblock 준비의 해제 경로를 함께 읽으세요.')])

    topic('SMB·세션과 공유 파일','파일시스템','fs/smb/client/connect.c','cifs_mount',
      '원격 서버의 공유 파일을 로컬 VFS처럼 다루려면 연결·인증·세션·캐시 일관성을 관리해야 합니다.',
      'SMB 클라이언트는 서버와 프로토콜을 협상하고 세션 인증과 공유 연결을 마련합니다. 파일 open은 원격 handle과 연결되며 lease·캐시·재연결·DFS 경로가 동작에 영향을 줍니다. 로컬 write 완료와 원격 서버의 영구 저장 보장은 별도 규약입니다.',
      'mount.cifs의 공유 경로·프로토콜·인증·캐시 옵션을 환경에 맞게 사용합니다. 암호를 공개 명령 기록에 넣지 않고 제공되는 자격 증명 관리 규약을 따릅니다. 서버·클라이언트·네트워크 오류를 구분합니다.',
      'cifs_mount의 dfs_mount_share·재연결 시 serverino 변경과 prefix path 처리를 읽으세요.',
      q('재연결한 다른 서버의 파일 ID를 이전 서버 ID와 무조건 동일하다고 볼 수 있는가?','서버 변경으로 ID가 달라질 수 있다','어떤 서버든 항상 같은 ID다','cifs_mount의 주석은 다른 서버 재연결 시 고유 ID가 달라져 serverino를 비활성화하는 이유를 설명합니다.'),
      q('SMB 공유가 로컬 경로처럼 보여도 파일 작업에 추가되는 경계는?','원격 서버·세션·네트워크 오류','모든 작업이 CPU 레지스터 안에서 끝남','VFS 경로 뒤에는 원격 요청과 서버 상태가 있습니다. 캐시와 재연결, 요청 완료와 내구성까지 구분해야 합니다.'),
      details=[detail('Session과 Tree connection','세션은 인증된 통신 상태이고 공유에 대한 tree connection은 접근할 자원의 연결입니다. 파일 handle은 그 아래 열린 파일의 상태입니다. 이 세 가지를 하나의 소켓 포인터로만 설명하면 복구 경로를 이해하기 어렵습니다.'),detail('DFS와 경로','DFS는 공유 경로를 다른 대상 서버로 해석할 수 있습니다. 대상 변경 시 prefix path와 파일 ID 규약을 다시 맞춰야 오래된 dentry를 잘못 재검증하지 않습니다.')])
